V C_NativeBattleCombatTests::m_test_original_gravebuster_zombie_death_leaves_attackable_nonproducing_spawn_grave_in_deathmatch(const Args& A) {
    V L_b;
    V L_before;
    V L_grave;
    V L_remnant;
    V L_remnants;
    V L_source;
    L_b = m_battle(Args({}, {{SY("zombies"), V::list({SV("zombie:脑光墓碑"), SV("zombie:墓碑吞噬者僵尸"), SV("zombie:普通僵尸")})}, {SY("deathmatch_seconds"), V(0.3)}}));
    L_grave = m_deploy(Args{L_b, SV("zombie"), SV("zombie:脑光墓碑"), V(17.0)});
    L_source = m_deploy(Args({L_b, SV("zombie"), SV("zombie:墓碑吞噬者僵尸"), V(17.0)}, {{SY("grave"), rdm(L_grave, &Obj::_pvp_id, SV("_pvp_id"))}}));
    (void)(m_cmd(Args{L_b, SV("zombie"), SV("command")}));
    (void)(callm(L_b, SY("step"), Args{V(75.0)}));
    (void)(m_assertTrue(Args{pvz::getattr(L_b, SY("deathmatch"))}));
    setm(L_source, &Obj::血量, SV("血量"), V(0.0));
    (void)(callm(L_b, SY("step"), Args{}));
    // PvP73 rule (user request 11-11): the dying 墓碑吞噬者僵尸 releases one bone where it stands instead of
    // leaving a remnant grave at once; the bone falls and a legal grave cell becomes a non-producing bone grave
    // that plants can attack and zombies can spawn from (the remaining checks below are unchanged).
    (void)(m_assertTrue(Args{V([&]() { V lg = py::iter_list(pvz::getattr(L_b, SY("log"))); for (size_t i_ = 0; i_ < lg.len(); ++i_) if (rd(lg.idx(int64_t(i_)), SV("event")) == SV("bone_released")) return true; return false; }())}));
    auto remnants_ = [&]() -> V { V out_ = V::list(); V L_u; { V it1_ = py::iter_list(callm(pvz::getattr(L_b, SY("units")), SY("values"), Args{})); for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) { L_u = it1_.idx(int64_t(i1_)); if (!((rd(L_u, SV("card_id")) == SV("zombie:残骸墓碑（非生产）")))) continue; out_.append(L_u); }}return out_; };
    for (int k_ = 0; k_ < 150 && remnants_().len() == 0; ++k_) (void)(callm(L_b, SY("step"), Args{}));
    L_remnants = remnants_();
    (void)(m_assertEqual(Args{V(1.0), py::len(L_remnants)}));
    (void)(m_assertTrue(Args{V([&]() { V lg = py::iter_list(pvz::getattr(L_b, SY("log"))); for (size_t i_ = 0; i_ < lg.len(); ++i_) if (rd(lg.idx(int64_t(i_)), SV("event")) == SV("bone_grave")) return true; return false; }())}));
    L_remnant = rd(L_remnants, V(0.0));
    (void)(m_assertGreater(Args{rd(L_remnant, SV("hp")), V(0.0)}));
    (void)(m_assertFalse(Args{rd(rd(L_remnant, SV("card")), SV("producer"))}));
    (void)(m_assertNotEqual(Args{SV("坟墓"), rd(rd(rd(rd(pvz::getattr(L_b, SY("g")), SV("ditu")), py::int_(floordiv((rdm(L_remnant, &Obj::y, SV("y")) - V(0.001)), V(48.0)))), py::int_(floordiv(rdm(L_remnant, &Obj::x, SV("x")), V(48.0)))), SV("方块"))}));
    pvz::setitem(pvz::getattr(L_b, SY("_grave_progress")), rd(L_remnant, SV("id")), V(999.0));
    L_before = rd(rd(rd(pvz::getattr(L_b, SY("players")), SV("zombie")), SV("stats")), SV("earned"));
    (void)(callm(L_b, SY("step"), Args{}));
    (void)(m_assertEqual(Args{L_before, rd(rd(rd(pvz::getattr(L_b, SY("players")), SV("zombie")), SV("stats")), SV("earned"))}));
    (void)(m_assertEqual(Args{SV(""), m_cmd(Args({L_b, SV("zombie"), SV("deploy")}, {{SY("card"), SV("zombie:普通僵尸")}, {SY("x"), rdm(L_remnant, &Obj::x, SV("x"))}, {SY("y"), (rdm(L_remnant, &Obj::y, SV("y")) - V(24.0))}, {SY("grave"), rd(L_remnant, SV("id"))}}))}));
    return V::none();
}

